{/* =========================
    PASSWORD
========================= */}

<div className="mb-2">

  <label
    htmlFor="password"
    className="form-label fw-semibold"
  >
    Password
  </label>

  <div className="position-relative">

    <input
      id="password"
      type={showPassword ? "text" : "password"}
      name="password"
      className="form-control form-control-lg pe-5"
      placeholder="Enter your password"
      value={loginData.password}
      onChange={handleChange}
      autoComplete="current-password"
      disabled={loading}
      required
    />

    <button
      type="button"
      onClick={() => setShowPassword((prev) => !prev)}
      disabled={loading}
      className="btn border-0 position-absolute top-50 end-0 translate-middle-y me-2 d-flex align-items-center justify-content-center"
      style={{
        width: "42px",
        height: "42px",
        background: "transparent",
        color: "#6c757d",
        fontSize: "18px",
      }}
      aria-label={
        showPassword ? "Hide password" : "Show password"
      }
    >
      {showPassword ? "🙈" : "👁️"}
    </button>

  </div>

</div>
